INSERT INTO engine_bug_queue (bug_class, title, severity, owner_cluster, root_cause, prevention_rule, probe_type, probe_logic, status, concepts_affected, fixed_in_files, discovered_in_session, row_type, fixed_at) VALUES
('state_subbeat_table_declares_motion_in_a_window_the_shipped_config_places_no_driver_in', 'A design sub-beat table authored build/read/dissolve and the JSON shipped an instant placement, leaving 8.4 s of byte-identical canvas under live narration', 'CRITICAL', 'alex:json_author', 'The skeleton per-state timing table is PROSE; the JSON reveal block is the only thing the renderer reads. A sub-beat that names MOTION ("builds 1500-7000", "dissolves 9000-11000") has no counterpart field unless the author writes a ramp, and an at_ms with no duration and no ramp is an INSTANT placement that satisfies every gate. THE EYE D5 scores a state as a WHOLE, so a state that moves anywhere passes while a third of it is a still frame. Measured on solids_of_revolution STATE_6 2026-08-28: 13 identical frames t=2100..10500 (sha256 d1916f879dcc), 8.4 s of a 28 s state, with the misconception narration playing over it; narration 45 words ~= 17.3 s against a measured 11.2 s motion window, which Rule 31 forbids and which a duration-based words_max cannot see.', 'Every sub-beat in a timing table that names MOTION must resolve to a NAMED DRIVER in the shipped JSON (a *_ramp, a *_ms fade window, or a camera_steps entry), and the build must prove it by hashing the dense series. Recompute the state''s words_max against the MEASURED motion window, never the authored duration.', 'js_eval', 'Hash every STATE_N__dense_*.png in run order; report maximal runs of identical hashes. For each run of >= 3 frames, assert it coincides with EITHER (a) an authored hold — a holds[] entry, or a gap between two authored drivers that the design sub-beat table names as a read/hold beat — OR (b) the post-timeline reveal-hold tail. THE DEFECT is a run overlapping a window in which a driver is DECLARED to be advancing. Measured on solids_of_revolution STATE_6: BEFORE, 13 identical frames t=2100..10500 (sha256 d1916f879dcc) against an authored "builds 1500-7000"; AFTER, with discs.n_ramp 1500-7000, 6 frames t=7000..10500 which coincide exactly with the authored "reads 7000-9000" hold plus an un-built dissolve. NEGATIVE CONTROL, same concept: STATE_4''s 12-frame run t=18200..25900 is its reveal-hold tail and must NOT flag. THE FIRST DRAFT OF THIS PROBE ("no run begins before the last authored driver ends") WOULD HAVE FLAGGED THE FIXED BUILD, and is recorded here as wrong: a probe that fails on a good build poisons the ratchet exactly as one that passes on a bad build does.', 'OPEN', ARRAY['solids_of_revolution']::text[], ARRAY[]::text[], 'founder_proxy Checkpoint B cycle 1, 2026-08-28', 'incident', NULL)
ON CONFLICT (bug_class) DO UPDATE SET
  title = EXCLUDED.title,
  severity = EXCLUDED.severity,
  owner_cluster = EXCLUDED.owner_cluster,
  root_cause = EXCLUDED.root_cause,
  prevention_rule = EXCLUDED.prevention_rule,
  probe_logic = EXCLUDED.probe_logic,
  status = EXCLUDED.status,
  concepts_affected = EXCLUDED.concepts_affected,
  fixed_in_files = EXCLUDED.fixed_in_files,
  fixed_at = EXCLUDED.fixed_at
WHERE engine_bug_queue.root_cause NOT LIKE '%CPB_SUBBEAT_NO_DRIVER_2026_08_28%'
  AND engine_bug_queue.status NOT IN ('FIXED', 'FALSE_POSITIVE');

