INSERT INTO engine_bug_queue (bug_class, title, severity, owner_cluster, root_cause, prevention_rule, probe_type, probe_logic, status, concepts_affected, fixed_in_files, discovered_in_session, row_type, fixed_at) VALUES
('founder_drive_playing_late_shot_lands_in_the_first_third_of_every_state_so_no_payoff_is_photographed', 'The three-shot per-state dump sampled at 18-37 percent of each state; every shot of the misconception state fell inside its dead window', 'MAJOR', 'peter_parker:visual_validator', 'playing_late is taken at a wall-clock offset rather than as a fraction of the state''s own authored timeline, so a 28 s state is photographed at 5.2 s. The founder reads this dump as the live-drive evidence for a state, and it currently cannot contain any state''s final teaching frame.', 'The three shots are placed as FRACTIONS of the state''s own timelineTotal (entry, mid, and after the last authored driver ends), not at fixed wall offsets. A dump meant to stand in for watching the sim must photograph the frame the state exists to produce.', 'js_eval', 'For each state in a founder_drive manifest, divide each shot''s simTimeMs by the state''s authored duration and assert the late shot exceeds 0.85. Measured on solids_of_revolution 2026-08-28: S2 4800/26000 = 0.18, S4 5088/26000 = 0.20, S6 5168/28000 = 0.18, S7 4880/24000 = 0.20, S3 8208/22000 = 0.37. All nine states fail; all three S6 shots landed inside the 8.4 s frozen window that the sub-beat row above describes, which is why the drive dump could not have surfaced it.', 'OPEN', ARRAY['solids_of_revolution']::text[], ARRAY[]::text[], 'founder_proxy Checkpoint B cycle 1, 2026-08-28', 'incident', NULL)
